-- =====================================================================
-- 005_payroll_approval_workflow.sql
--
-- Segregation of duties for payroll: the Payroll Officer (maker) processes a
-- period into a run, and the Approver (checker) approves / returns / releases
-- it. A run is locked the moment it is Approved or Released.
--
-- payroll_runs.status : Submitted | Approved | Returned | Released
--   Submitted = generated by the maker, waiting for the checker
--   Approved  = checker accepted it; payslips / deductions / allowances /
--               loan payments are now locked
--   Returned  = checker sent it back with remarks; editable again
--   Released  = checker authorised payment release (terminal state)
--
-- Existing rows are treated as already released (they were processed before
-- the workflow existed), so they are locked too.
--
-- Idempotent: safe to run more than once.
-- =====================================================================

-- Older installs already have `status` as VARCHAR(30) NULL; make it NOT NULL
-- with the workflow default. (No-op on columns that are already correct.)
ALTER TABLE `payroll_runs`
    ADD COLUMN IF NOT EXISTS `status` VARCHAR(20) NOT NULL DEFAULT 'Submitted' AFTER `run_date`;

ALTER TABLE `payroll_runs`
    MODIFY COLUMN `status` VARCHAR(20) NOT NULL DEFAULT 'Submitted';

ALTER TABLE `payroll_runs`
    ADD COLUMN IF NOT EXISTS `submitted_by`        BIGINT       NULL DEFAULT NULL AFTER `status`,
    ADD COLUMN IF NOT EXISTS `submitted_at`        DATETIME     NULL DEFAULT NULL AFTER `submitted_by`,
    ADD COLUMN IF NOT EXISTS `approved_by`         BIGINT       NULL DEFAULT NULL AFTER `submitted_at`,
    ADD COLUMN IF NOT EXISTS `approved_at`         DATETIME     NULL DEFAULT NULL AFTER `approved_by`,
    ADD COLUMN IF NOT EXISTS `returned_by`         BIGINT       NULL DEFAULT NULL AFTER `approved_at`,
    ADD COLUMN IF NOT EXISTS `returned_at`         DATETIME     NULL DEFAULT NULL AFTER `returned_by`,
    ADD COLUMN IF NOT EXISTS `release_approved_by` BIGINT       NULL DEFAULT NULL AFTER `returned_at`,
    ADD COLUMN IF NOT EXISTS `release_approved_at` DATETIME     NULL DEFAULT NULL AFTER `release_approved_by`,
    ADD COLUMN IF NOT EXISTS `remarks`             VARCHAR(500) NULL DEFAULT NULL AFTER `release_approved_at`;

-- Legacy statuses ('Completed', empty, NULL) become Released.
UPDATE `payroll_runs`
   SET `status` = 'Released'
 WHERE `status` IS NULL
    OR `status` NOT IN ('Submitted', 'Approved', 'Returned', 'Released');

CREATE INDEX IF NOT EXISTS `idx_payroll_runs_status` ON `payroll_runs` (`status`);
CREATE INDEX IF NOT EXISTS `idx_payroll_runs_submitted_by` ON `payroll_runs` (`submitted_by`);
CREATE INDEX IF NOT EXISTS `idx_payroll_runs_approved_by` ON `payroll_runs` (`approved_by`);
